SELECT * FROM artifacts JOIN artifact_authorlists ON artifact_authorlists.al_artifactid = artifacts.a_id WHERE func_jsort(artifact_authorlists.al_authorlist) LIKE '%paolo%' AND func_jsortvalues(artifact_authorlists.al_authorlist) LIKE '%ana%' AND func_stem(artifacts.a_title) LIKE '%field%' AND func_filterstopwords(artifacts.a_title) LIKE '%study%' AND func_keywords(artifacts.a_journal) LIKE '%bio%' AND func_stem(artifacts.a_journal) LIKE '%phys%' AND func_stem(artifacts.a_publisher) LIKE '%press%' AND func_keywords(artifacts.a_publisher) LIKE '%sci%' AND artifacts.a_year BETWEEN 2008 AND 2010;
SELECT * FROM artifacts JOIN views_stats ON views_stats.vs_artifactid = artifacts.a_id WHERE func_removeshortterms(artifacts.a_title) LIKE '%river%' AND func_filterstopwords(artifacts.a_title) LIKE '%data%' AND func_keywords(artifacts.a_title) LIKE '%data%' AND func_stem(artifacts.a_title) LIKE '%genom%' AND func_removeshortterms(artifacts.a_journal) LIKE '%rev%' AND func_filterstopwords(artifacts.a_journal) LIKE '%inform%' AND func_stem(artifacts.a_publisher) LIKE '%spring%' AND func_keywords(artifacts.a_publisher) LIKE '%press%' AND func_filterstopwords(artifacts.a_publisher) LIKE '%ltd%' AND func_stem(artifacts.a_journal) LIKE '%comput%' AND views_stats.vs_count > 3 AND artifacts.a_year BETWEEN 2012 AND 2014;
SELECT * FROM artifacts JOIN artifact_authorlists ON artifact_authorlists.al_artifactid = artifacts.a_id WHERE func_jsort(artifact_authorlists.al_authorlist) LIKE '%simone%' AND func_jsortvalues(artifact_authorlists.al_authorlist) LIKE '%liu%' AND func_removeshortterms(artifacts.a_title) LIKE '%growth%' AND func_filterstopwords(artifacts.a_title) LIKE '%express%' AND func_keywords(artifacts.a_title) LIKE '%network%' AND func_stem(artifacts.a_journal) LIKE '%nature%' AND func_keywords(artifacts.a_journal) LIKE '%learn%' AND func_filterstopwords(artifacts.a_journal) LIKE '%rev%' AND func_stem(artifacts.a_publisher) LIKE '%else%' AND func_stem(artifacts.a_title) LIKE '%quantum%' AND artifacts.a_year BETWEEN 2006 AND 2008;
